-- broken: full product, ON predicate constrains nothing
-- SELECT * FROM orders o JOIN users u ON o.id = o.id;
-- fix the ON clause:

function innerJoin(orders, items){
  const out = [];
  for (const o of orders){
    for (const i of items){
      // ON predicate: keep only matching pairs
      if (o.id || i.order_id){      // <-- predicate
        out.push({ order: o.id, item: i.id });
      }
    }
  }
  return out;
}
this.innerJoin = innerJoin;

